test('unseen intent lifecycle invalidates another tab grant',async()=>{
 const role='player';
 const fakePeer={name:'mock-peer',enforce:'pre',resolveId(id){if(id==='peerjs')return '\0mock-peer'},load(id){if(id==='\0mock-peer')return `export default class Peer { constructor(){ this.handlers={};globalThis.__peer=this } on(k,f){this.handlers[k]=f;return this} connect(id){const c={peer:id,open:true,handlers:{},on(k,f){this.handlers[k]=f;return this},sent:[],off(){return this},send(message){this.sent.push(message)},close(){this.open=false}};globalThis.__connection=c;return c} destroy(){} }`}};
 const vite=await createServer({configFile:false,ssr:{noExternal:['peerjs']},plugins:[fakePeer],server:{middlewareMode:true},appType:'custom',logLevel:'silent'});const dom=new JSDOM('<div id="root"></div>',{url:'http://localhost/'});const old={window:globalThis.window,document:globalThis.document,navigator:globalThis.navigator,localStorage:globalThis.localStorage,act:globalThis.IS_REACT_ACT_ENVIRONMENT};const held=new Set();Object.defineProperty(dom.window.navigator,'locks',{value:{request:async(name,options,callback)=>{if(held.has(name))return callback(null);held.add(name);try{return await callback({name})}finally{held.delete(name)}}},configurable:true});globalThis.window=dom.window;globalThis.document=dom.window.document;Object.defineProperty(globalThis,'navigator',{value:dom.window.navigator,configurable:true});globalThis.localStorage=dom.window.localStorage;globalThis.IS_REACT_ACT_ENVIRONMENT=true;let root,rootB;
 try{
 const {createInitialContext}=await vite.ssrLoadModule('/utils/gameContext.ts'),{useGameLogic}=await vite.ssrLoadModule('/hooks/useGameLogic.ts'),{LocalizationProvider}=await vite.ssrLoadModule('/context/LocalizationContext.tsx');const c=createInitialContext({universe:'fantasy',playerName:'Host',race:'Human',charClass:'Warrior',initialPrompt:'Start',startingYear:1000,startingMonth:'January',startingDay:1,startTime:'08:00',weather:'Clear'},'en');c.currentTurnNumber=3;c.gameSettings.cooperativeGameType='FullParty';const item={existedId:'sword',name:'Sword',durability:'100%',equipmentSlot:'MainHand',weight:0,volume:0,count:1};const host={...c.playerCharacter,playerId:'host',name:'Host'},guest={...host,playerId:'guest',name:'Guest',inventory:[item]};c.playerCharacter=host;c.players=[host,guest];
 const state={playerCharacter:host,players:[host,guest],activePlayerIndex:0,currentLocationData:c.currentLocation,activeQuests:[],completedQuests:[],encounteredNPCs:[],encounteredFactions:[],enemiesData:[],alliesData:[],playerCustomStates:[],plotOutline:null,worldStateFlags:[],worldEventsLog:[],imageCache:{},networkRole:'host',myPeerId:'host',hostPeerId:'host',peers:[],isConnectedToHost:true};const save={gameContext:c,gameState:state,gameHistory:[{sender:'gm',content:'Hello'}],gameLog:[],combatLog:[],lastJsonResponse:null,sceneImagePrompt:null,timestamp:new Date().toISOString()};
 let api;function Harness(){api=useGameLogic({language:'en',setLanguage:()=>{}});return null}root=createRoot(document.getElementById('root'));await act(async()=>root.render(React.createElement(StrictMode,null,React.createElement(LocalizationProvider,null,React.createElement(Harness)))));await act(async()=>{await new Promise(resolve=>setTimeout(resolve,100))});await act(async()=>api.joinGame('host',role,'Guest'));await act(async()=>{globalThis.__peer.handlers.open('guest');globalThis.__connection.handlers.open()});const sync=revision=>globalThis.__connection.handlers.data({type:'full_sync',payload:{saveFile:structuredClone(save),protocol:{version:1,sessionId:'session',revision},editCapability:{protocol:'host-edit',version:1}}});await act(async()=>sync(1));assert.equal(api.gameState.networkRole,role);assert.equal(api.gameState.playerCharacter.playerId,role==='player'?'guest':'host');assert.equal(api.isLoading,false);
 const connA=globalThis.__connection;let resolveSend;const sendGate=new Promise(resolve=>resolveSend=resolve);connA.send=function(message){this.sent.push(message);if(message.type==='client_edit_command')return sendGate};
 const element=document.createElement('div');document.body.appendChild(element);let apiB;function HarnessB(){apiB=useGameLogic({language:'en',setLanguage:()=>{}});return null}rootB=createRoot(element);
 await act(async()=>rootB.render(React.createElement(StrictMode,null,React.createElement(LocalizationProvider,null,React.createElement(HarnessB)))));await act(async()=>{await new Promise(resolve=>setTimeout(resolve,100))});
 await act(async()=>apiB.joinGame('host',role,'Guest'));await act(async()=>{globalThis.__peer.handlers.open('guest');globalThis.__connection.handlers.open()});const connB=globalThis.__connection;
 await act(async()=>connB.handlers.data({type:'full_sync',payload:{saveFile:structuredClone(save),protocol:{version:1,sessionId:'session',revision:1},editCapability:{protocol:'host-edit',version:1}}}));
 await act(async()=>{api.equipItem(item,'MainHand');await new Promise(resolve=>setTimeout(resolve,100))});assert.equal(api.clientEditIntents[0].status,'pending');
 await act(async()=>{resolveSend();await new Promise(resolve=>setTimeout(resolve,50))});await act(async()=>{api.discardClientEditIntent(api.clientEditIntents[0].command.commandId);await new Promise(resolve=>setTimeout(resolve,100))});assert.equal(api.clientEditIntents.length,0);assert.equal(apiB.clientEditIntents.length,0,'second tab never observed the intent');
 await act(async()=>apiB.sendMessage('must not start on old grant'));assert.equal(apiB.gameHistory.filter(m=>m.sender==='player').length,0,'unseen lifecycle invalidates old grant before a turn');
 await act(async()=>{apiB.equipItem(item,'MainHand');await new Promise(resolve=>setTimeout(resolve,100))});assert.equal(connB.sent.filter(m=>m.type==='client_edit_command').length,0,'unseen lifecycle must invalidate old grant before another edit');assert.ok(connB.sent.some(m=>m.type==='request_full_sync'),'fresh sync requested');
 const request=connB.sent.filter(m=>m.type==='request_full_sync').at(-1);await act(async()=>connB.handlers.data({type:'full_sync',payload:{saveFile:structuredClone(save),protocol:{version:1,sessionId:'session',revision:2},editCapability:{protocol:'host-edit',version:1}}}));
 await act(async()=>{apiB.equipItem(item,'MainHand');await new Promise(resolve=>setTimeout(resolve,50))});assert.equal(connB.sent.filter(m=>m.type==='client_edit_command').length,0,'unrelated snapshot cannot unlock refresh');
 await act(async()=>connB.handlers.data({type:'full_sync',payload:{saveFile:structuredClone(save),protocol:{version:1,sessionId:'session',revision:3},syncRequestId:request.payload.syncRequestId,editCapability:{protocol:'host-edit',version:1}}}));await act(async()=>{apiB.equipItem(item,'MainHand');await new Promise(resolve=>setTimeout(resolve,100))});assert.equal(connB.sent.filter(m=>m.type==='client_edit_command').length,1,'matching committed refresh enables a new explicit edit');await act(async()=>{apiB.discardClientEditIntent(apiB.clientEditIntents[0].command.commandId);await new Promise(resolve=>setTimeout(resolve,100))});
 }finally{if(rootB)await act(async()=>rootB.unmount());if(root)await act(async()=>root.unmount());delete globalThis.__peer;delete globalThis.__connection;globalThis.window=old.window;globalThis.document=old.document;Object.defineProperty(globalThis,'navigator',{value:old.navigator,configurable:true});globalThis.localStorage=old.localStorage;globalThis.IS_REACT_ACT_ENVIRONMENT=old.act;dom.window.close();await vite.close()}
});

test('persisted turn intent survives reload and blocks client edits and turns',async()=>{
 const role='player';
 const fakePeer={name:'mock-peer',enforce:'pre',resolveId(id){if(id==='peerjs')return '\0mock-peer'},load(id){if(id==='\0mock-peer')return `export default class Peer { constructor(){ this.handlers={};globalThis.__peer=this } on(k,f){this.handlers[k]=f;return this} connect(id){const c={peer:id,open:true,handlers:{},on(k,f){this.handlers[k]=f;return this},sent:[],off(){return this},send(message){this.sent.push(message)},close(){this.open=false}};globalThis.__connection=c;return c} destroy(){} }`}};
 const vite=await createServer({configFile:false,ssr:{noExternal:['peerjs']},plugins:[fakePeer],server:{middlewareMode:true},appType:'custom',logLevel:'silent'});const dom=new JSDOM('<div id="root"></div>',{url:'http://localhost/'});const old={window:globalThis.window,document:globalThis.document,navigator:globalThis.navigator,localStorage:globalThis.localStorage,act:globalThis.IS_REACT_ACT_ENVIRONMENT};Object.defineProperty(dom.window.navigator,'locks',{value:{request:async(name,options,callback)=>callback({name})},configurable:true});globalThis.window=dom.window;globalThis.document=dom.window.document;Object.defineProperty(globalThis,'navigator',{value:dom.window.navigator,configurable:true});globalThis.localStorage=dom.window.localStorage;globalThis.IS_REACT_ACT_ENVIRONMENT=true;let root;
 try{
 const {createInitialContext}=await vite.ssrLoadModule('/utils/gameContext.ts'),{useGameLogic}=await vite.ssrLoadModule('/hooks/useGameLogic.ts'),{LocalizationProvider}=await vite.ssrLoadModule('/context/LocalizationContext.tsx');const c=createInitialContext({universe:'fantasy',playerName:'Host',race:'Human',charClass:'Warrior',initialPrompt:'Start',startingYear:1000,startingMonth:'January',startingDay:1,startTime:'08:00',weather:'Clear'},'en');c.currentTurnNumber=3;c.gameSettings.cooperativeGameType='FullParty';const item={existedId:'sword',name:'Sword',durability:'100%',equipmentSlot:'MainHand',weight:0,volume:0,count:1};const host={...c.playerCharacter,playerId:'host',name:'Host'},guest={...host,playerId:'guest',name:'Guest',inventory:[item]};c.playerCharacter=host;c.players=[host,guest];
 const state={playerCharacter:host,players:[host,guest],activePlayerIndex:0,currentLocationData:c.currentLocation,activeQuests:[],completedQuests:[],encounteredNPCs:[],encounteredFactions:[],enemiesData:[],alliesData:[],playerCustomStates:[],plotOutline:null,worldStateFlags:[],worldEventsLog:[],imageCache:{},networkRole:'host',myPeerId:'host',hostPeerId:'host',peers:[],isConnectedToHost:true};const save={gameContext:c,gameState:state,gameHistory:[{sender:'gm',content:'Hello'}],gameLog:[],combatLog:[],lastJsonResponse:null,sceneImagePrompt:null,timestamp:new Date().toISOString()};
 const {createClientTurnIntent,transitionClientTurnIntent}=await vite.ssrLoadModule('/utils/clientEditIntentStore.ts');const turnIntent=await createClientTurnIntent({hostPeerId:'host',command:{version:1,sessionId:'session',commandId:'00000000-0000-4000-8000-000000000111',playerId:'guest',base:{version:1,sessionId:'session',revision:1},kind:'action',text:'A secret action',image:null}});await transitionClientTurnIntent(turnIntent,'pending');
 let api;function Harness(){api=useGameLogic({language:'en',setLanguage:()=>{}});return null}root=createRoot(document.getElementById('root'));await act(async()=>root.render(React.createElement(StrictMode,null,React.createElement(LocalizationProvider,null,React.createElement(Harness)))));await act(async()=>{await new Promise(resolve=>setTimeout(resolve,100))});await act(async()=>api.joinGame('host',role,'Guest'));await act(async()=>{globalThis.__peer.handlers.open('guest');globalThis.__connection.handlers.open()});const sync=revision=>globalThis.__connection.handlers.data({type:'full_sync',payload:{saveFile:structuredClone(save),protocol:{version:1,sessionId:'session',revision},editCapability:{protocol:'host-edit',version:1}}});await act(async()=>sync(1));assert.equal(api.gameState.networkRole,role);assert.equal(api.gameState.playerCharacter.playerId,role==='player'?'guest':'host');assert.equal(api.isLoading,false);
 assert.equal(api.clientTurnIntents.length,1);assert.equal(api.clientTurnIntents[0].status,'unknown');await act(async()=>{api.equipItem(item,'MainHand');await api.sendMessage('Continue');await new Promise(resolve=>setTimeout(resolve,100))});assert.ok(api.error);assert.equal(globalThis.__connection.sent.filter(m=>m.type==='client_edit_command'||m.type==='turn_result_from_player').length,0);await act(async()=>{api.discardClientTurnIntent(turnIntent.command.commandId);await new Promise(resolve=>setTimeout(resolve,100))});assert.equal(api.clientTurnIntents.length,0);

 }finally{if(root)await act(async()=>root.unmount());delete globalThis.__peer;delete globalThis.__connection;globalThis.window=old.window;globalThis.document=old.document;Object.defineProperty(globalThis,'navigator',{value:old.navigator,configurable:true});globalThis.localStorage=old.localStorage;globalThis.IS_REACT_ACT_ENVIRONMENT=old.act;dom.window.close();await vite.close()}
});
